package dev.homecontrol.app;

import android.app.*;
import android.content.Intent;
import android.os.*;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

/** A stable bottom sheet: refresh patches labels, and never rebuilds the root/buttons. */
public final class MijiaPanelActivity extends Activity {
    private AppUi ui;private String id,schema="!";private JSONObject device=new JSONObject();private LinearLayout controls;
    private TextView title,subtitle,feedback;private boolean foreground,destroyed,running,readQueued,accountUnavailable;
    private final Handler main=new Handler(Looper.getMainLooper());private final HaierPanelQueue queue=new HaierPanelQueue();
    private final Map<String,SliderBinding> sliders=new LinkedHashMap<>();
    private final Map<String,Binding> bindings=new LinkedHashMap<>();
    private final Runnable poll=()->{if(foreground){refresh();schedule();}};
    private static final class Binding {JSONObject definition;final TextView button;final boolean action;Binding(JSONObject d,TextView v,boolean a){definition=d;button=v;action=a;}}
    @Override public void onCreate(Bundle state){super.onCreate(state);id=getIntent().getStringExtra("id");if(id==null||!id.startsWith("mijia:")){finish();return;}AppUi.systemBars(this);ui=new AppUi(this);JSONObject cached=MijiaCloud.cached(this,id);if(cached!=null)device=cached;else{JSONArray list=DeviceStore.devices(this);for(int i=0;i<list.length();i++){JSONObject d=list.optJSONObject(i);if(d!=null&&id.equals(d.optString("id")))device=d;}}build();update();}
    @Override protected void onResume(){super.onResume();foreground=true;refresh();schedule();}
    @Override protected void onPause(){foreground=false;main.removeCallbacks(poll);queue.clearWaiting();readQueued=false;super.onPause();}
    @Override protected void onDestroy(){destroyed=true;main.removeCallbacksAndMessages(null);super.onDestroy();}
    private void schedule(){main.removeCallbacks(poll);if(foreground)main.postDelayed(poll,20000);}
    private void build(){
        getWindow().setBackgroundDrawableResource(android.R.color.transparent);getWindow().addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);getWindow().setDimAmount(.32f);getWindow().setLayout(-1,-1);
        FrameLayout root=new FrameLayout(this);root.setOnClickListener(v->finish());root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets b=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(b.left+ui.dp(12),b.top,b.right+ui.dp(12),b.bottom+ui.dp(12));return insets;});
        LinearLayout sheet=ui.column();sheet.setClickable(true);sheet.setPadding(ui.dp(20),ui.dp(20),ui.dp(20),ui.dp(14));sheet.setBackground(ui.shape(ui.surface,26));LinearLayout header=ui.row();ImageView icon=new ImageView(this);icon.setImageBitmap(DeviceIcons.make(this,device,ui.accent));header.addView(icon,new LinearLayout.LayoutParams(ui.dp(38),ui.dp(38)));
        LinearLayout labels=ui.column();title=ui.text("米家设备",20,ui.text,true);title.setSingleLine(true);title.setEllipsize(TextUtils.TruncateAt.END);labels.addView(title);subtitle=ui.text("状态待更新",12,ui.muted,false);subtitle.setSingleLine(true);subtitle.setEllipsize(TextUtils.TruncateAt.END);labels.addView(subtitle);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.leftMargin=ui.dp(12);header.addView(labels,lp);
        FrameLayout refresh=new FrameLayout(this);refresh.setContentDescription("刷新米家状态");refresh.setBackground(ui.ripple(ui.pale,14));refresh.addView(ui.icon(AppUi.REFRESH,ui.accent,20),new FrameLayout.LayoutParams(ui.dp(20),ui.dp(20),Gravity.CENTER));refresh.setOnClickListener(v->refresh());header.addView(refresh,new LinearLayout.LayoutParams(ui.dp(44),ui.dp(44)));sheet.addView(header);ui.space(sheet,12);
        feedback=ui.text("正在读取设备能力与状态…",13,ui.accent,false);feedback.setLines(2);feedback.setEllipsize(TextUtils.TruncateAt.END);sheet.addView(feedback,new LinearLayout.LayoutParams(-1,ui.dp(44)));ui.space(sheet,8);
        controls=ui.column();ScrollView scroll=new ScrollView(this);scroll.addView(controls);sheet.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));ui.space(sheet,12);
        TextView more=ui.text("更多  ›",14,ui.accent,true);more.setGravity(Gravity.CENTER);more.setBackground(ui.ripple(ui.background,16));more.setOnClickListener(v->startActivity(new Intent(this,MijiaActivity.class)));sheet.addView(more,new LinearLayout.LayoutParams(-1,ui.dp(48)));
        root.addView(sheet,new FrameLayout.LayoutParams(-1,Math.round(getResources().getDisplayMetrics().heightPixels*.78f),Gravity.BOTTOM));setContentView(root);
    }
    private void update(){
        text(title,device.optString("title","米家设备"));text(subtitle,accountUnavailable?"请在更多中重新登录米家":device.optString("subtitle","状态待更新"));JSONArray props=device.optJSONArray("capabilities"),actions=device.optJSONArray("actions");if(props==null)props=new JSONArray();if(actions==null)actions=new JSONArray();String shape=DeviceProfiles.kind(device)+":"+device.optString("model")+":"+shape(props,actions);
        if(!schema.equals(shape)){schema=shape;bindings.clear();sliders.clear();controls.removeAllViews();String kind=DeviceProfiles.kind(device);Set<String> primary=new HashSet<>();
            if("light".equals(kind))lightControls(props,primary);
            if("cooker".equals(kind)||"microwave".equals(kind))kitchenControls(props,actions,primary);
            if("lock".equals(kind)){controls.addView(ui.text("设备状态",17,ui.text,true));ui.space(controls,8);controls.addView(ui.text("一次性密码、开锁、用户管理和视频仍在适配，当前显示可读取的状态。",13,ui.muted,false));ui.space(controls,12);}
            LinearLayout root=controls;boolean specialized="light".equals(kind)||"cooker".equals(kind)||"microwave".equals(kind);
            if(specialized){LinearLayout advanced=ui.column();advanced.setVisibility(View.GONE);TextView toggle=shortcut("其他设备功能  ⌄",()->advanced.setVisibility(advanced.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));root.addView(toggle,new LinearLayout.LayoutParams(-1,ui.dp(46)));ui.space(root,8);root.addView(advanced);controls=advanced;}
            List<JSONObject> group=new ArrayList<>();String service="";for(int i=0;i<props.length();i++){JSONObject p=props.optJSONObject(i);if(p==null||primary.contains(p.optString("key")))continue;if(!p.optString("service").equals(service)){addGrid(group,false);group.clear();service=p.optString("service");if(!service.isEmpty()){ui.space(controls,10);controls.addView(ui.text(service,14,ui.muted,true));ui.space(controls,8);}}group.add(p);}addGrid(group,false);group.clear();
            for(int i=0;i<actions.length();i++){JSONObject a=actions.optJSONObject(i);if(a!=null&&!primary.contains(a.optString("key"))&&!(specialized&&(a.optString("name").contains("self-check")||a.optString("name").contains("setting"))))group.add(a);}if(!group.isEmpty()){ui.space(controls,14);controls.addView(ui.text("设备操作",14,ui.muted,true));ui.space(controls,8);addGrid(group,true);}
            if(bindings.isEmpty()&&sliders.isEmpty())controls.addView(ui.text("设备未提供可读取的通用功能，已保留设备卡片。",14,ui.muted,false));controls=root;
        }
        boolean online=device.optInt("state")==1&&!accountUnavailable;
        for(SliderBinding slider:sliders.values())slider.patch(props,online);
        for(Binding b:bindings.values()){JSONObject p=MijiaModel.find(b.action?actions:props,b.definition.optString("key"));if(p==null)continue;b.definition=p;String label=p.optString("title");if(!b.action)label+="\n"+(p.optBoolean("stale")&&p.has("value")?"上次：":"")+MijiaModel.display(p);else if(!p.optBoolean("supported"))label+="\n暂不支持此参数";if(b.action&&"kitchen".equals(b.button.getTag())){int aiid=p.optInt("aiid");label=aiid==2?"取消烹饪":aiid==3?"暂停":aiid==6?"继续":label;}if(!b.action&&"p:2:1".equals(p.optString("key"))&&("cooker".equals(DeviceProfiles.kind(device))||"microwave".equals(DeviceProfiles.kind(device)))&&p.has("value"))label="状态\n"+(p.optBoolean("stale")?"上次：":"")+KitchenState.label(device.optString("model"),p.optInt("value"));text(b.button,label);boolean enabled=online&&(b.action?p.optBoolean("supported"):p.optBoolean("writable"));if(b.button.isEnabled()!=enabled){b.button.setEnabled(enabled);b.button.setAlpha(enabled?1f:.6f);}b.button.setContentDescription((b.action?"米家操作":"米家属性")+p.optString("title"));}
    }
    private final class SliderBinding {
        final String key;final SeekBar bar;final TextView label;JSONObject definition;boolean touching;final int min,step;
        SliderBinding(JSONObject p){definition=p;key=p.optString("key");JSONArray range=p.optJSONArray("range");min=range.optInt(0);int max=range.optInt(1);step=Math.max(1,range.optInt(2));LinearLayout box=ui.column();box.setPadding(ui.dp(16),ui.dp(12),ui.dp(16),ui.dp(10));box.setBackground(ui.shape(ui.background,18));label=ui.text(p.optString("title"),15,ui.text,true);box.addView(label);bar=new SeekBar(MijiaPanelActivity.this);bar.setContentDescription("米家滑块"+p.optString("title"));bar.setMax((max-min)/step);box.addView(bar,new LinearLayout.LayoutParams(-1,ui.dp(44)));bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar v){touching=true;}public void onProgressChanged(SeekBar v,int value,boolean user){if(user)text(label,definition.optString("title")+"  "+(min+value*step)+("kelvin".equals(definition.optString("unit"))?" K":"%"));}public void onStopTrackingTouch(SeekBar v){touching=false;enqueue(key,min+v.getProgress()*step);}});controls.addView(box);ui.space(controls,10);}
        void patch(JSONArray props,boolean online){JSONObject p=MijiaModel.find(props,key);if(p==null)return;definition=p;if(!touching){text(label,p.optString("title")+"  "+(p.optBoolean("stale")&&p.has("value")?"上次：":"")+MijiaModel.display(p));if(p.opt("value") instanceof Number)bar.setProgress(Math.max(0,Math.min(bar.getMax(),(p.optInt("value")-min)/step)));}bar.setEnabled(online&&p.optBoolean("writable")&&p.has("value"));}
    }
    private TextView shortcut(String label,Runnable click){TextView v=ui.text(label,14,ui.accent,true);v.setGravity(Gravity.CENTER);v.setPadding(ui.dp(12),ui.dp(10),ui.dp(12),ui.dp(10));v.setBackground(ui.ripple(ui.background,16));v.setOnClickListener(w->click.run());return v;}
    private void lightControls(JSONArray props,Set<String> primary){
        JSONObject power=null;for(int i=0;i<props.length();i++){JSONObject p=props.optJSONObject(i);if(p!=null&&"on".equals(p.optString("name"))&&p.optBoolean("writable")){power=p;break;}}if(power!=null){controls.addView(button(power,false),new LinearLayout.LayoutParams(-1,ui.dp(88)));ui.space(controls,10);primary.add(power.optString("key"));}
        for(int i=0;i<props.length();i++){JSONObject p=props.optJSONObject(i);if(p==null)continue;String name=p.optString("name");if(("brightness".equals(name)||"color-temperature".equals(name))&&p.optBoolean("writable")&&p.optJSONArray("range")!=null){sliders.put(p.optString("key"),new SliderBinding(p));primary.add(p.optString("key"));}}
        List<JSONObject> tiles=new ArrayList<>();for(int i=0;i<props.length();i++){JSONObject p=props.optJSONObject(i);if(p!=null&&(MijiaModel.color(p)||"mode".equals(p.optString("name")))){tiles.add(p);primary.add(p.optString("key"));}}addGrid(tiles,false);
        if("yeelink.light.bslamp2".equals(device.optString("model"))){controls.addView(shortcut("定时与延时关闭  ›",()->startActivity(new Intent(this,LightTimerActivity.class).putExtra("id",id))),new LinearLayout.LayoutParams(-1,ui.dp(48)));ui.space(controls,12);}
    }
    private void kitchenControls(JSONArray props,JSONArray actions,Set<String> primary){
        List<JSONObject> status=new ArrayList<>();for(String key:new String[]{"p:2:1","xiaomi.microwave.cm20l".equals(device.optString("model"))?"p:2:5":"p:2:8"}){JSONObject p=MijiaModel.find(props,key);if(p!=null){status.add(p);primary.add(key);}}addGrid(status,false);
        controls.addView(ui.text("常用模式",16,ui.text,true));ui.space(controls,8);
        JSONArray common=new JSONArray(),extra=new JSONArray();try{JSONArray modes=DeviceProfiles.modes(device.optString("model"));Set<String> names=new HashSet<>(Arrays.asList("精煮","快煮","煮粥","保温","火力加热","快热","解冻","除菌"));for(int i=0;i<modes.length();i++){JSONObject mode=modes.getJSONObject(i);(names.contains(mode.optString("title"))?common:extra).put(mode);}}catch(Exception ignored){}
        modeTiles(common);LinearLayout parent=controls;FoldView expanded=panelFold("extra","扩展模式",AppUi.DEVICES);controls=expanded.body;modeTiles(extra);controls.addView(shortcut("设备菜单与食谱  ›",()->startActivity(new Intent(this,RecipesActivity.class).putExtra("id",id).putExtra("tab","modes"))),new LinearLayout.LayoutParams(-1,ui.dp(48)));controls=parent;controls.addView(expanded);ui.space(controls,10);
        FoldView timer=panelFold("timer","定时 / 预约",AppUi.REFRESH);List<JSONObject> timers=new ArrayList<>();for(int i=0;i<props.length();i++){JSONObject p=props.optJSONObject(i);if(p==null)continue;String name=p.optString("name");if(p.optBoolean("writable")&&(name.contains("timer")||name.contains("appointment")||name.contains("delay"))){timers.add(p);primary.add(p.optString("key"));}}
        controls=timer.body;if(timers.isEmpty())controls.addView(ui.text("当前型号暂未提供可用的独立预约功能。",13,ui.muted,false));else addGrid(timers,false);controls=parent;controls.addView(timer);ui.space(controls,10);
        for(int i=0;i<actions.length();i++){JSONObject a=actions.optJSONObject(i);if(a!=null)primary.add(a.optString("key"));}List<JSONObject> operations=new ArrayList<>();for(int i=0;i<actions.length();i++){JSONObject a=actions.optJSONObject(i);if(a!=null&&a.optInt("siid")==2&&a.optInt("aiid")>=2&&a.optInt("aiid")<=6&&a.optJSONArray("inputs")!=null&&a.optJSONArray("inputs").length()==0){JSONObject copy;try{copy=new JSONObject(a.toString());int aiid=a.optInt("aiid");copy.put("title",aiid==2?"取消烹饪":aiid==3?"暂停":aiid==6?"继续":a.optString("title"));}catch(Exception e){continue;}operations.add(copy);primary.add(a.optString("key"));}}addGrid(operations,true);for(JSONObject a:operations){Binding b=bindings.get(a.optString("key"));if(b!=null)b.button.setTag("kitchen");}
    }
    private FoldView panelFold(String key,String label,int icon){String setting="panel_fold:"+id+":"+key;return new FoldView(this,ui,label,null,icon,"1".equals(DeviceStore.preference(this,setting,"0")),open->DeviceStore.putPreference(this,setting,open?"1":"0"));}
    private void modeTiles(JSONArray modes){for(int i=0;i<modes.length();i+=2){LinearLayout row=ui.row();for(int j=i;j<Math.min(i+2,modes.length());j++){JSONObject mode=modes.optJSONObject(j);if(mode==null)continue;String title=mode.optString("title");int value=mode.optInt("value");TextView tile=shortcut(title,()->{if("chunmi.cooker.js5".equals(device.optString("model"))&&value!=5){new AlertDialog.Builder(this).setTitle("启动"+title+"？").setMessage("请确认已放好食材并合盖。确认后将启动设备。").setPositiveButton("确认启动",(d,w)->enqueue("a:2:1",new JSONArray().put(value))).setNegativeButton("取消",null).show();}else startActivity(new Intent(this,RecipesActivity.class).putExtra("id",id).putExtra("tab","modes").putExtra("focusMode",title));});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,ui.dp(48),1);if(j>i)p.leftMargin=ui.dp(8);row.addView(tile,p);}if(row.getChildCount()==1){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,0,1);p.leftMargin=ui.dp(8);row.addView(new View(this),p);}controls.addView(row);ui.space(controls,8);}}
    private String shape(JSONArray props,JSONArray actions){StringBuilder s=new StringBuilder();for(JSONArray list:new JSONArray[]{props,actions})for(int i=0;i<list.length();i++){JSONObject p=list.optJSONObject(i);if(p!=null)s.append(p.optString("key")).append(':').append(p.optString("title")).append(':').append(p.optBoolean("writable")).append(':').append(p.optBoolean("supported")).append(':').append(p.optString("format")).append(':').append(p.opt("range")).append(':').append(p.opt("choices")).append(':').append(p.opt("inputs")).append(';');}return s.toString();}
    private void addGrid(List<JSONObject> items,boolean action){for(int i=0;i<items.size();i+=2){LinearLayout row=ui.row();row.addView(button(items.get(i),action),new LinearLayout.LayoutParams(0,ui.dp(76),1));row.addView(new View(this),new LinearLayout.LayoutParams(ui.dp(8),1));if(i+1<items.size())row.addView(button(items.get(i+1),action),new LinearLayout.LayoutParams(0,ui.dp(76),1));else row.addView(new View(this),new LinearLayout.LayoutParams(0,0,1));controls.addView(row);ui.space(controls,8);}}
    private TextView button(JSONObject definition,boolean action){TextView v=ui.text("",14,ui.text,true);v.setGravity(Gravity.CENTER);v.setPadding(ui.dp(8),ui.dp(7),ui.dp(8),ui.dp(7));v.setMaxLines(3);v.setEllipsize(TextUtils.TruncateAt.END);v.setBackground(ui.ripple(ui.background,16));v.setFocusable(true);v.setClickable(true);Binding b=new Binding(definition,v,action);bindings.put(definition.optString("key"),b);v.setOnClickListener(view->edit(b));return v;}
    private void edit(Binding binding){JSONObject p=binding.definition;if(binding.action){editAction(p);return;}if("bool".equals(p.optString("format"))&&p.opt("value") instanceof Boolean){String desired=queue.desired(p.optString("key"),String.valueOf(p.opt("value")));enqueue(p.optString("key"),"true".equals(desired)?Boolean.FALSE:Boolean.TRUE);return;}showProperty(p);}
    private void showProperty(JSONObject p){FormField field=new FormField(p);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(p.optString("title")).setView(field.container).setPositiveButton("设置",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{try{enqueue(p.getString("key"),field.value());dialog.dismiss();}catch(Exception e){field.error(CloudDevices.error(e,e.getMessage()==null?"请输入设备支持的数值":e.getMessage()));}}));dialog.show();}
    private void editAction(JSONObject a){JSONArray inputs=a.optJSONArray("inputs");List<FormField> fields=new ArrayList<>();LinearLayout form=ui.column();form.setPadding(ui.dp(8),0,ui.dp(8),0);if(inputs!=null)for(int i=0;i<inputs.length();i++){JSONObject p=inputs.optJSONObject(i);if(p==null)continue;FormField field=new FormField(p);fields.add(field);form.addView(field.container);}if(fields.isEmpty())form.addView(ui.text("确认执行「"+a.optString("title")+"」？",15,ui.text,false));ScrollView scroll=new ScrollView(this);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(a.optString("title")).setView(scroll).setPositiveButton("执行",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{try{JSONArray values=new JSONArray();for(FormField field:fields)values.put(field.value());enqueue(a.getString("key"),values);dialog.dismiss();}catch(Exception e){Toast.makeText(this,e.getMessage()==null?"请检查操作参数":e.getMessage(),Toast.LENGTH_LONG).show();}}));dialog.show();}
    private final class FormField {
        final JSONObject property;final LinearLayout container;Spinner choices;EditText input;JSONArray values;SeekBar[] rgb;
        FormField(JSONObject p){property=p;container=ui.column();container.setPadding(ui.dp(20),ui.dp(8),ui.dp(20),ui.dp(12));container.addView(ui.text(p.optString("title"),14,ui.text,true));ui.space(container,8);if(MijiaModel.color(p)){rgb=new SeekBar[3];View preview=new View(MijiaPanelActivity.this);container.addView(preview,new LinearLayout.LayoutParams(-1,ui.dp(42)));int color=p.optInt("value",0xffffff);String[] names={"红","绿","蓝"};for(int i=0;i<3;i++){ui.space(container,10);container.addView(ui.text(names[i],13,ui.muted,false));rgb[i]=new SeekBar(MijiaPanelActivity.this);rgb[i].setMax(255);rgb[i].setProgress((color>>(16-i*8))&255);container.addView(rgb[i]);}preview.setBackground(ui.shape(0xff000000|colorValue(),12));for(SeekBar bar:rgb)bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int progress,boolean user){preview.setBackground(ui.shape(0xff000000|colorValue(),12));}});return;}values=p.optJSONArray("choices");List<String> labels=new ArrayList<>();if(values!=null&&values.length()>0){for(int i=0;i<values.length();i++){JSONObject c=values.optJSONObject(i);labels.add(c==null?"":c.optString("description"));}}else if("bool".equals(p.optString("format"))){labels.add("关闭");labels.add("开启");}if(!labels.isEmpty()){choices=new Spinner(MijiaPanelActivity.this);choices.setAdapter(new ArrayAdapter<String>(MijiaPanelActivity.this,android.R.layout.simple_spinner_dropdown_item,labels));if(p.has("value")){if(values!=null&&values.length()>0){for(int i=0;i<values.length();i++)if(MijiaValue.equivalent(p.opt("value"),values.optJSONObject(i).opt("value")))choices.setSelection(i);}else choices.setSelection(Boolean.TRUE.equals(p.opt("value"))?1:0);}container.addView(choices);}else{input=new EditText(MijiaPanelActivity.this);input.setSingleLine(true);input.setSaveEnabled(false);input.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO_EXCLUDE_DESCENDANTS);String format=p.optString("format");input.setInputType("string".equals(format)?InputType.TYPE_CLASS_TEXT:InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);if(p.has("value"))input.setText(String.valueOf(p.opt("value")));JSONArray range=p.optJSONArray("range");if(range!=null&&range.length()==3)input.setHint(range.optString(0)+" 至 "+range.optString(1)+"，步长 "+range.optString(2));container.addView(input);}}
        int colorValue(){return rgb[0].getProgress()<<16|rgb[1].getProgress()<<8|rgb[2].getProgress();}
        Object value()throws Exception{Object value;if(rgb!=null)value=colorValue();else if(choices!=null)value=values!=null&&values.length()>0?values.getJSONObject(choices.getSelectedItemPosition()).get("value"):choices.getSelectedItemPosition()==1;else value=MijiaValue.parse(property.optString("format"),input.getText().toString());if(!MijiaModel.valid(property,value))throw new IllegalArgumentException("数值超出设备支持范围，或不符合步长要求");return value;}
        void error(String message){if(input!=null)input.setError(message);else Toast.makeText(MijiaPanelActivity.this,message,Toast.LENGTH_LONG).show();}
    }
    private void enqueue(String key,Object value){KeyguardManager keyguard=getSystemService(KeyguardManager.class);if(keyguard==null||keyguard.isDeviceLocked()){text(feedback,"请先解锁手机");return;}String wrapped=new JSONArray().put(value).toString();if(wrapped==null){text(feedback,"操作参数无效");return;}queue.offer(key,wrapped.substring(1,wrapped.length()-1));pump();}
    private void refresh(){readQueued=true;pump();}
    private void pump(){if(running||destroyed||!foreground)return;HaierPanelQueue.Command command=queue.next();if(command==null&&!readQueued)return;boolean read=command==null;if(read)readQueued=false;running=true;
        new Thread(()->{JSONObject latest=null;String message="";boolean auth=false;try{if(read)latest=MijiaCloud.readDevice(this,id);else message=MijiaCloud.control(this,id,command.key,command.value);}catch(Exception e){auth=e instanceof MijiaCloud.Authentication;message=CloudDevices.error(e,read?"状态暂未更新，已保留原有控件":"操作结果未确认，请刷新；不会自动重复发送");}final JSONObject next=latest;final String result=message;final boolean unavailable=auth;
            main.post(()->{running=false;if(command!=null)queue.completed(command);if(destroyed)return;if(next!=null){device=next;accountUnavailable=false;}else{JSONObject cached=MijiaCloud.cached(this,id);if(cached!=null)device=cached;if(unavailable)accountUnavailable=true;}if(!result.isEmpty())text(feedback,result);else if(read)text(feedback,device.optBoolean("statusReadFailed")?"部分状态暂未更新，已保留上次状态":"状态已更新");update();DeviceStore.remember(this,DeviceStore.devices(this));DeviceWidget.updateAll(this);if(command!=null)readQueued=true;pump();});
        },read?"MijiaRead":"MijiaCommand").start();
    }
    private static void text(TextView view,String text){if(!text.contentEquals(view.getText()))view.setText(text);}
}
